(function(){
"use strict";

const data = JSON.parse(
  new TextDecoder("utf-8").decode(
    Uint8Array.from(atob(""),c=>c.charCodeAt(0))
  )
);

const dict = new Map(data);
const pairs = [...dict.entries()].sort((a,b)=>b[0].length-a[0].length);
const originals = new WeakMap();

let lang = "RU";
try{
  lang = localStorage.getItem("shipa-lang")==="KZ"?"KZ":"RU";
}catch(e){}

function translate(source){
  let output=source;

  const trimmed=source.trim();
  if(dict.has(trimmed)){
    return source.replace(trimmed,dict.get(trimmed));
  }

  // Only replace phrases or whole words. Avoid replacing
  // portions inside unrelated words or prices.
  for(const [ru,kz] of pairs){
    if(!ru||ru.length<3)continue;
    if(!output.includes(ru))continue;

    const start=output.indexOf(ru);
    const before=start>0?output[start-1]:"";
    const after=output[start+ru.length]||"";
    const letters=/[A-Za-zА-Яа-яЁёӘәҒғҚқҢңӨөҰұҮүҺһІі]/;

    if(letters.test(before)||letters.test(after))continue;

    output=output.slice(0,start)+kz+output.slice(start+ru.length);
  }

  return output;
}

function visit(node){
  if(!node||!node.parentElement)return;

  const tag=node.parentElement.tagName;
  if(["SCRIPT","STYLE","TEXTAREA","CODE","PRE"].includes(tag))return;

  const value=node.nodeValue;
  let old=originals.get(node);

  if(!old||old.last!==value){
    old={source:value,last:value};
  }

  const next=lang==="KZ"?translate(old.source):old.source;

  old.last=next;
  originals.set(node,old);

  if(next!==value){
    node.nodeValue=next;
  }
}

function scan(root){
  if(!root)return;

  if(root.nodeType===3){
    visit(root);
    return;
  }

  if(root.nodeType!==1)return;

  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  while(walker.nextNode())visit(walker.currentNode);
}

let changing=false;

function apply(){
  if(changing)return;
  changing=true;

  try{
    scan(document.body);
    document.documentElement.lang=lang==="KZ"?"kk":"ru";
  }finally{
    changing=false;
  }
}

function setLanguage(value){
  if(value!=="RU"&&value!=="KZ")return;

  lang=value;

  try{
    localStorage.setItem("shipa-lang",value);
  }catch(e){}

  apply();
}

function init(){
  apply();

  const observer=new MutationObserver(mutations=>{
    if(changing)return;

    changing=true;

    try{
      for(const m of mutations){
        if(m.type==="characterData"){
          visit(m.target);
        }else if(m.type==="childList"){
          m.addedNodes.forEach(scan);
        }
      }
    }finally{
      changing=false;
    }
  });

  observer.observe(document.body,{
    subtree:true,
    childList:true,
    characterData:true
  });

  document.addEventListener("click",e=>{
    const button=e.target.closest&&e.target.closest("button");

    if(!button)return;

    const value=(button.textContent||"").trim();

    if(value==="RU"||value==="KZ"){
      setTimeout(()=>setLanguage(value),0);
    }
  },true);
}

if(document.readyState==="loading"){
  document.addEventListener("DOMContentLoaded",init,{once:true});
}else{
  init();
}

window.ShipaBookingLocale={
  set:setLanguage,
  get:()=>lang
};

})();